begin;
-- Real synthetic sessions for member JWT fixtures; rows roll back with this test.
insert into auth.sessions(id,user_id) select md5('pgtap-session:'||id::text)::uuid,id from auth.users;
set local search_path = extensions, public, private;
select plan(15);
update private.private_locations set verified_at = now() where profile_id::text like '10000000-%';
select ok(private.matches_discovery_identity_groups(array['gay','trans'], array['gay','bi','trans']), 'alternatives within a section match');
select ok(not private.matches_discovery_identity_groups(array['gay'], array['gay','trans']), 'both sections must match');
select ok(private.matches_discovery_identity_groups(array['queer'], null), 'empty choice includes everyone');
select ok(not has_function_privilege('anon', 'private.validate_profile_cover()', 'execute'), 'anonymous cannot invoke cover guard');
select ok(not has_column_privilege('anon', 'public.profiles', 'conversation_prompt', 'update'), 'anonymous cannot edit prompts');
set local role authenticated;
select set_config('request.jwt.claim.sub', '10000000-0000-0000-0000-000000000002', true);
select set_config('request.jwt.claims',(coalesce(nullif(current_setting('request.jwt.claims',true),''),'{}')::jsonb||jsonb_build_object('sub','10000000-0000-0000-0000-000000000002','session_id',md5('pgtap-session:10000000-0000-0000-0000-000000000002')::uuid))::text,true);
select set_config('request.jwt.claim.role', 'authenticated', true);
select lives_ok($$update public.profiles set cover_photo_id='20000000-0000-0000-0000-000000000001', conversation_prompt='Kaffi eða göngutúr?', interests=array['Kaffi','Göngur'] where id=auth.uid()$$, 'owner can set approved cover and prompt');
select throws_ok($$update public.profiles set conversation_prompt=repeat('a',161) where id=auth.uid()$$, '23514', null, 'prompt length enforced on server');
select throws_ok($$update public.profiles set cover_photo_id='20000000-0000-0000-0000-000000000002' where id=auth.uid()$$, '23514', 'cover_requires_own_approved_photo', 'another member photo rejected');
select set_config('request.jwt.claim.sub', '10000000-0000-0000-0000-000000000003', true);
select set_config('request.jwt.claims',(coalesce(nullif(current_setting('request.jwt.claims',true),''),'{}')::jsonb||jsonb_build_object('sub','10000000-0000-0000-0000-000000000003','session_id',md5('pgtap-session:10000000-0000-0000-0000-000000000003')::uuid))::text,true);
select throws_ok($$update public.profiles set cover_photo_id='20000000-0000-0000-0000-000000000002' where id=auth.uid()$$, '23514', 'cover_requires_own_approved_photo', 'own pending photo rejected');
select set_config('request.jwt.claim.sub', '10000000-0000-0000-0000-000000000001', true);
select set_config('request.jwt.claims',(coalesce(nullif(current_setting('request.jwt.claims',true),''),'{}')::jsonb||jsonb_build_object('sub','10000000-0000-0000-0000-000000000001','session_id',md5('pgtap-session:10000000-0000-0000-0000-000000000001')::uuid))::text,true);
select is(public.get_public_profile('10000000-0000-0000-0000-000000000002')->>'cover_photo_id', '20000000-0000-0000-0000-000000000001', 'approved cover returned through protected profile RPC');
select is(public.get_public_profile('10000000-0000-0000-0000-000000000002')->>'conversation_prompt', 'Kaffi eða göngutúr?', 'prompt returned with public profile');
select is(public.get_public_profile('10000000-0000-0000-0000-000000000002')->'interests'->>0, 'Kaffi', 'interest order preserved');
select is((select count(*) from public.discover_nearby('{"identities":["gay","nonbinary"]}')), 0::bigint, 'RPC requires orientation and gender together');
reset role;
update public.profiles set is_profile_visible=false where id='10000000-0000-0000-0000-000000000002';
set local role authenticated;
select is(public.get_public_profile('10000000-0000-0000-0000-000000000002'), null::jsonb, 'hidden cover and prompt remain private');
reset role;
update public.profiles set is_profile_visible=true where id='10000000-0000-0000-0000-000000000002';
insert into public.blocks(blocker_id, blocked_id) values ('10000000-0000-0000-0000-000000000002','10000000-0000-0000-0000-000000000001');
set local role authenticated;
select is(public.get_public_profile('10000000-0000-0000-0000-000000000002'), null::jsonb, 'block keeps customized profile private');
select * from finish();
rollback;
